// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 guess) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 2 ether);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        vm.roll(block.number + 2);

        vm.prank(actor);
        bool ok1; try c.settle() { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1, "first settle must not revert");

        vm.prank(actor);
        bool ok2; try c.settle() { ok2 = true; } catch { ok2 = false; }
        assertTrue(!ok2, "second settle must revert because block was reset");
    }
}
